@mode(game)

window(800, 600, "FreeLang-G Hello World")

fn update(dt: f32) {
  // 게임 로직은 나중에
}

fn draw() {
  clear_bg(RAYWHITE)
  draw_text("Hello, FreeLang-G!", 50, 50, 20, DARKGRAY)
}

loop {
  update(get_delta())
  draw()
}

@mode(game)

window(800, 600, "Pong - FreeLang-G")

// Ball
let ball_x: f32 = 400.0
let ball_y: f32 = 300.0
let ball_vx: f32 = 5.0
let ball_vy: f32 = 4.0
let ball_size: f32 = 8.0

// Paddles
let pad1_x: f32 = 20.0
let pad1_y: f32 = 250.0
let pad1_w: f32 = 15.0
let pad1_h: f32 = 100.0

let pad2_x: f32 = 765.0
let pad2_y: f32 = 250.0
let pad2_w: f32 = 15.0
let pad2_h: f32 = 100.0

let pad_speed: f32 = 6.0

// Score
let score1: f32 = 0.0
let score2: f32 = 0.0

fn update(dt: f32) {
  // Update ball position
  ball_x = ball_x + ball_vx
  ball_y = ball_y + ball_vy

  // Ball collision with top/bottom
  if ball_y - ball_size < 0.0 || ball_y + ball_size > 600.0 {
    ball_vy = ball_vy * -1.0
  }

  // Ball collision with left/right (reset)
  if ball_x < 0.0 {
    score2 = score2 + 1.0
    ball_x = 400.0
    ball_y = 300.0
    ball_vx = 5.0
  }

  if ball_x > 800.0 {
    score1 = score1 + 1.0
    ball_x = 400.0
    ball_y = 300.0
    ball_vx = -5.0
  }

  // Ball collision with paddles
  // Left paddle
  if ball_x - ball_size < pad1_x + pad1_w &&
     ball_y > pad1_y &&
     ball_y < pad1_y + pad1_h {
    ball_vx = ball_vx * -1.0
    ball_x = pad1_x + pad1_w + ball_size
  }

  // Right paddle
  if ball_x + ball_size > pad2_x &&
     ball_y > pad2_y &&
     ball_y < pad2_y + pad2_h {
    ball_vx = ball_vx * -1.0
    ball_x = pad2_x - ball_size
  }
}

fn draw() {
  clear_bg(BLACK)

  // Draw ball
  draw_circle(ball_x, ball_y, ball_size, WHITE)

  // Draw paddles
  draw_rect(pad1_x, pad1_y, pad1_w, pad1_h, WHITE)
  draw_rect(pad2_x, pad2_y, pad2_w, pad2_h, WHITE)

  // Draw center line (dashed)
  draw_line(400, 0, 400, 600, WHITE)

  // Draw score (simple text - left/right)
  draw_text("Score 1", 100, 50, 20, WHITE)
  draw_text("Score 2", 600, 50, 20, WHITE)
}

on_key(KEY_W) {
  if pad1_y > 0.0 {
    pad1_y = pad1_y - pad_speed
  }
}

on_key(KEY_S) {
  if pad1_y < 600.0 - pad1_h {
    pad1_y = pad1_y + pad_speed
  }
}

on_key(KEY_UP) {
  if pad2_y > 0.0 {
    pad2_y = pad2_y - pad_speed
  }
}

on_key(KEY_DOWN) {
  if pad2_y < 600.0 - pad2_h {
    pad2_y = pad2_y + pad_speed
  }
}

loop {
  update(get_delta())
  draw()
}

