// 🏦 FreeLang Bank System - Transaction Module
// 거래 엔진 (900+ lines)

// 거래 타입
enum TransactionType {
  Deposit,    // 입금
  Withdraw,   // 출금
  Transfer,   // 계좌이체
  Interest,   // 이자
}

// 거래 상태
enum TransactionStatus {
  Pending,    // 대기
  Completed,  // 완료
  Failed,     // 실패
  Reversed,   // 취소
}

// 거래 레코드
type Transaction = record {
  txn_id: str,                    // 거래 ID
  from_account_id: str,           // 출금 계좌
  to_account_id: str,             // 입금 계좌
  amount: f64,                    // 거래액
  txn_type: TransactionType,      // 거래 타입
  status: TransactionStatus,      // 거래 상태
  created_at: i64,                // 생성일
  completed_at: i64,              // 완료일 (0 = 미완료)
  description: str,               // 설명
  fee: f64,                       // 수수료
}

// ========================================
// 1️⃣ 거래 생성
// ========================================

fn create_transaction(
  from_account: str,
  to_account: str,
  amount: f64,
  txn_type: TransactionType,
  description: str
) -> Transaction {
  record {
    txn_id: generate_transaction_id(),
    from_account_id: from_account,
    to_account_id: to_account,
    amount: amount,
    txn_type: txn_type,
    status: Pending,
    created_at: now(),
    completed_at: 0,
    description: description,
    fee: 0.0,
  }
}

// ========================================
// 2️⃣ 거래 ID 생성
// ========================================

fn generate_transaction_id() -> str {
  "TXN-" + to_str(now()) + "-" + random_string(6)
}

// ========================================
// 3️⃣ 거래 수수료 계산
// ========================================

fn calculate_fee(txn_type: TransactionType, amount: f64) -> f64 {
  match txn_type {
    Deposit => 0.0,              // 입금: 무료
    Withdraw => 0.0,             // 출금: 무료 (초과는 유료)
    Transfer => if amount > 1000.0 {
      amount * 0.005             // 이체: 1000 초과 시 0.5% 수수료
    } else {
      1.0                        // 최소 $1 수수료
    },
    Interest => 0.0,             // 이자: 무료
  }
}

// ========================================
// 4️⃣ ACID 거래 처리
// ========================================

// 거래 구조: Atomicity, Consistency, Isolation, Durability

fn process_transfer_transaction(
  txn: Transaction,
  from_balance: f64,
  to_balance: f64
) -> (Transaction, f64, f64) {
  // 1. VALIDATION (일관성)
  if txn.amount <= 0.0 {
    return (
      record {
        txn_id: txn.txn_id,
        from_account_id: txn.from_account_id,
        to_account_id: txn.to_account_id,
        amount: txn.amount,
        txn_type: txn.txn_type,
        status: Failed,
        created_at: txn.created_at,
        completed_at: now(),
        description: txn.description,
        fee: 0.0,
      },
      from_balance,
      to_balance
    )
  }

  if from_balance < txn.amount {
    return (
      record {
        txn_id: txn.txn_id,
        from_account_id: txn.from_account_id,
        to_account_id: txn.to_account_id,
        amount: txn.amount,
        txn_type: txn.txn_type,
        status: Failed,
        created_at: txn.created_at,
        completed_at: now(),
        description: txn.description,
        fee: 0.0,
      },
      from_balance,
      to_balance
    )
  }

